export default function Intro() {   
    const { isLaptop } = useContext(WindowContext);
    console.log(process.env.PUBLIC_URL);
    const imageList = [
        "/assets/images/common/main-character1.png",
        "/assets/images/common/main-character2.png",
        "/assets/images/common/main-character3.png",
        "/assets/images/common/main-character4.png",
    ];
    const [currentImage, setCurrentImage] = useState(0);
    useEffect(() => {
        if (currentImage < imageList.length - 1) {
            const interval = setInterval(() => {
                setCurrentImage(currentImage + 1);
            }, 2000);
            return () => clearInterval(interval);
        }
    }, [currentImage]);
    const variants = {
        hidden: {
            opacity: 0,
            // scale: 0.8,
        },
        visible: {
            opacity: 1,
            scale: 1,
            transition: {
                duration: 0.5,
                ease: "easeOut",
                opacity: { duration: 0.5 },
                scale: { duration: 0.5 }
            }
        }
    };
    return (
        <Wrapper>
            <Container>
                <Content>
                    <div className="intro-content">
                        <h1>Trade Smarter, <br /> Profit Bigger</h1>
                        <CopyContainer>
                            <div>
                                <h6>CA</h6>
                                {
                                    !isLaptop ? <h6 className="text-gray">3FBC4500B8CA527A8A5DB9725143A73DC66C06AE</h6> : <h6 className="text-gray">3FBC4500B8CA527A8A5DB9 ...</h6>
                                }
                            </div>
                            {
                                !isLaptop ? <CopyButton text="3FBC4500B8CA527A8A5DB9725143A73DC66C06AE" needImg={true} needSmall={false} /> : <CopyButton text="3FBC4500B8CA527A8A5DB9725143A73DC66C06AE" needImg={false} needSmall={true} />
                            }
                        </CopyContainer>
                    </div>
                    <ImageContainer>
                        {imageList.map((img, index) => (
                            <motion.img
                                key={index}
                                variants={variants}
                                initial="hidden"
                                animate={currentImage === index ? "visible" : "hidden"}
                                src={img}
                                style={{ display: currentImage === index ? 'block' : 'none' }}
                            />
                        ))}
                    </ImageContainer>
                </Content>
            </Container>
        </Wrapper>
    );
}