import { useChartFetchAPI } from "../fetchAPI";

export const useCoinList = (url: string) => {
    return useChartFetchAPI(url, ['coinList'], {
        staleTime:Infinity,
        select: (data) => {
            return data.tickers ;
        }
    });
}

export const useCandleData = (url: string, symbol: string, limit: number = 0,isHeikin = false,options:any = {}) => {
    const { enabled = true,staleTime = 300000, select,onSuccess } = options;
    const transformUrl = `${url}?ticker=${symbol}&limit=${limit}`;
    
    return useChartFetchAPI(transformUrl, [isHeikin ? 'heikinCandleData' : 'candleData', symbol], {
        enabled,
        staleTime,
        select: select || ((data) => {
            return {
                candleData: data.result.map((item: any) => ({
                    time: item.time,
                    open: item.open,
                    high: item.high,
                    low: item.low,
                    close: item.close,
                })),
                aoData: caculateAO(data.result),
                pinkData: data.result.map((item: any) => ({
                    time: item.time,
                    value: item.pink,
                })),
            };
        }),
        onSuccess: (data: any) => {
            if (onSuccess) {
                onSuccess(data);
            }
        }
    });
};

