const caculateAO = (candleData: any) => {
    let data = [];
    for (let i = 0; i < candleData.length; i++) {
        if (candleData[i].open != "") {
            let sma5 = 0, sma34 = 0;

            // 5일 이동 평균 계산 (데이터가 부족한 경우, 가능한 범위 내에서 계산)
            let start = Math.max(0, i - 4);  // 시작 인덱스가 음수가 되지 않도록 함
            for (let j = start; j <= i; j++) {
                sma5 += candleData[j].open;
            }
            sma5 /= (i - start + 1);  // 유효한 데이터 개수로 나눔

            // 34일 이동 평균 계산 (데이터가 부족한 경우, 가능한 범위 내에서 계산)
            let start34 = Math.max(0, i - 33);
            for (let j = start34; j <= i; j++) {
                sma34 += candleData[j].open;
            }
            sma34 /= (i - start34 + 1);  // 유효한 데이터 개수로 나눔

            let ao = sma5 - sma34;
            let time = candleData[i].time;

            data.push({ time: time, value: ao });
        }
    }
    // console.log('data',data);
    
    return data;
}

export const useCandleSignalData = (url: string, symbol: string, limit: number = 0,options:any={}) => {
    const { enabled = true,staleTime = 300000, select,onSuccess } = options;
    const transformUrl = `${url}?ticker=${symbol}&limit=${limit}`;
    return useChartFetchAPI(transformUrl, ['candleSignalData', symbol], {
        enabled,
        staleTime,
        select: select || ((data) => {
            let result = data.result.none;
            let signalMarkers: any[] = [];
            let filteredSignal = setSignalMarkers(result,signalMarkers);
            return  filteredSignal 
        }),
        onSuccess: (data: any) => {
            if (onSuccess) {
                onSuccess(data);
            }
        }
    });
}

const setSignalMarkers = (array: any,marker: any) => {
    // console.log('array',array);
    
    for(let i=0; i < array.length; i++){
        let signal = array[i].signal;
        let timestamp = array[i].time;
        let firstChar = signal.charAt(0);
        let secondChar = signal.charAt(1);
        let lastTwoChars = signal.slice(-2);
        if(firstChar === "L"){
            if(secondChar === "1"){
            marker.push({
                time: timestamp,
                position: 'belowBar',
                color: '#A3FF12',
                shape: 'arrowUp',
                text: signal,
                size: 1.5
                });
            } else if(secondChar === "2" || secondChar === "3"){
                marker.push({
                    time: timestamp,
                    position: 'belowBar',
                    color: '#A3FF12',
                    shape: 'arrowUp',
                    text: "L",
                    size: 1.5
                });
            }
        } else if(firstChar === "S"){
            if(secondChar === "1"){
                marker.push({
                    time: timestamp,
                    position: 'aboveBar',
                    color: '#F82552',
                    shape: 'arrowDown',
                    text: signal,
                    size: 1.5
                });
            } else if(secondChar === "2" || secondChar === "3"){
                marker.push({
                    time: timestamp,
                    position: 'aboveBar',
                    color: '#F82552',
                    shape: 'arrowDown',
                    text: "S",
                    size: 1.5
                });
            }
        }
    }
    return marker
}

