import { useQuery } from 'react-query';

interface FetchAPIOptions {
    enabled?: boolean;
    select?: (data: any) => any;
    staleTime?: number;
    onSuccess?: (data: any) => void;
}

export const useChartFetchAPI = (
    url: string, 
    queryKey: string | string[], 
    options: FetchAPIOptions = {}
) => {
    const { enabled = true,select, staleTime = 300000, onSuccess } = options;

    return useQuery({
        queryKey: Array.isArray(queryKey) ? queryKey : [queryKey],
        queryFn: async () => {
            const response = await fetch(`${process.env.REACT_APP_CHART_URL}${url}`);
            return response.json();
        },
        enabled,
        staleTime,
        select,
        onSuccess,
    });
};